export class FocusHelper {
  private static INACTIVE_TAB_INDEX: number = -1;
  private static ACTIVE_TAB_INDEX: number = 0;

  static onKeyUp = (focusStyle: string, event: KeyboardEvent): string =>
    event.code === 'Tab' ? 'keyboard' : focusStyle;

  static onMouseDown = (): string => 'mouse';
  static onBlur = (): string => '';

  static handleHostTabIndex = (disabled: boolean, activeTabIndex?: number) => {
    if (disabled) {
      return FocusHelper.INACTIVE_TAB_INDEX;
    }

    if (activeTabIndex === undefined) {
      return FocusHelper.ACTIVE_TAB_INDEX;
    }

    return activeTabIndex;
  };

  private static getAllNodes = (root: HTMLElement) => {
    const nodes = [root];
    let node = root.shadowRoot ? root.shadowRoot.firstChild : root.firstChild;
    while (node) {
      nodes.push(...this.getAllNodes(node as HTMLElement));
      node = node.nextSibling;
    }
    return nodes;
  };

  static getNextFocusableElement = (currentElement: HTMLElement, container = document.body) => {
    const allNodes = this.getAllNodes(container);
    let foundCurrent = false;
    for (const node of allNodes) {
      if (node === currentElement) {
        foundCurrent = true;
        continue;
      }
      if (foundCurrent && this.isFocusable(node)) {
        return node;
      }
    }
    return null;
  };

  static getPreviousFocusableElement = (currentElement: HTMLElement, container = document.body) => {
    const allNodes = this.getAllNodes(container);
    let lastFocusable = null;
    for (const node of allNodes) {
      if (node === currentElement) {
        return lastFocusable;
      }
      if (this.isFocusable(node)) {
        lastFocusable = node;
      }
    }
    return null;
  };

  private static isFocusable = (element: HTMLElement) => {
    if (!element || element.nodeType !== Node.ELEMENT_NODE) return false;

    if ('disabled' in element && element.disabled) return false;

    const tabindex = element.getAttribute('tabindex');
    if (tabindex && parseInt(tabindex) < 0) return false;

    const style = getComputedStyle(element);
    if (style.visibility === 'hidden' || style.display === 'none') return false;

    return element.matches(
      'a[href], area[href], input:not([type="hidden"]), select, textarea, button, iframe, object, embed, [contenteditable], [tabindex]'
    );
  };
}
